cfg = dict(defaults)
for env_key, value in env.items():
    if not env_key.startswith("APP_"):
        continue

    key = env_key[4:].lower()
    if key not in cfg:
        continue

    default = cfg[key]
    if isinstance(default, bool):
        normalized = value.strip().lower()
        if normalized in {"true", "1", "yes", "on"}:
            cfg[key] = True
        elif normalized in {"false", "0", "no", "off"}:
            cfg[key] = False
        else:
            raise ValueError(f"invalid boolean value for {env_key}: {value!r}")
    else:
        cfg[key] = type(default)(value)

return cfg
